async def act(page):
    """
    Apply the existing Telephone filter value (2065555555) by clicking the fully-scoped Search
    button, then search the Customers grid for a row containing 2065555555 across pages.
    If a matching row is found, print the customer's Name and Email (each on its own line).
    If not found after paging, print "NOT FOUND".

    This function uses accessibility-role selectors only (.get_by_role and .filter(has=...)).
    """
    import asyncio
    import re

    # Utility: attempt to dismiss any obvious popup that might block clicks using role selectors.
    try:
        # Try dialog role first
        dialogs = page.get_by_role("dialog")
        if await dialogs.count() > 0:
            dlg = dialogs.first
            btns = dlg.get_by_role("button")
            if await btns.count() > 0:
                try:
                    await btns.first.click()
                    await asyncio.sleep(0.35)
                except Exception:
                    pass

        # Try generic close buttons by name (regex) as fallback
        close_re = re.compile(r"^(close|×|dismiss|no\s*thanks|ok)$", re.I)
        close_buttons = page.get_by_role("button", name=close_re)
        if await close_buttons.count() > 0:
            try:
                await close_buttons.first.click()
                await asyncio.sleep(0.35)
            except Exception:
                pass

        close_links = page.get_by_role("link", name=close_re)
        if await close_links.count() > 0:
            try:
                await close_links.first.click()
                await asyncio.sleep(0.35)
            except Exception:
                pass
    except Exception:
        # Non-fatal if dismissal fails
        pass

    # Click the Search button using a fully-scoped path (toolbar table -> Reset Filter Search cell -> Search button)
    try:
        toolbar_tables = page.get_by_role("table").filter(
            has=page.get_by_role("cell", name="Export to: CSV Export")
        )
        if await toolbar_tables.count() > 0:
            toolbar_table = toolbar_tables.first
            search_cells = toolbar_table.get_by_role("cell", name="Reset Filter Search")
            if await search_cells.count() > 0:
                search_button = search_cells.first.get_by_role("button", name="Search")
                if await search_button.count() > 0:
                    try:
                        await search_button.first.click()
                    except Exception:
                        # Try dismissing a popup and retry once
                        try:
                            dialogs = page.get_by_role("dialog")
                            if await dialogs.count() > 0:
                                db = dialogs.first.get_by_role("button")
                                if await db.count() > 0:
                                    await db.first.click()
                                    await asyncio.sleep(0.25)
                            await search_button.first.click()
                        except Exception:
                            # give up clicking Search; we'll still try to read the table
                            pass
    except Exception:
        # non-fatal; proceed to attempt reading results
        pass

    # Wait shortly for grid to refresh
    try:
        await page.wait_for_load_state("networkidle", timeout=5000)
    except Exception:
        await asyncio.sleep(0.8)

    # Scope the customers table by the 'Telephone' header link
    customers_tables = page.get_by_role("table").filter(
        has=page.get_by_role("link", name="Telephone")
    )
    if await customers_tables.count() == 0:
        print("NOT FOUND")
        return
    customers_table = customers_tables.first

    # Search current page and paginate up to 7 pages
    max_pages = 7
    for _ in range(max_pages):
        matching_rows = customers_table.get_by_role("row").filter(has_text="2065555555")
        if await matching_rows.count() > 0:
            row = matching_rows.first
            cells = row.get_by_role("cell")
            if await cells.count() > 3:
                name = (await cells.nth(2).inner_text()).strip()
                email = (await cells.nth(3).inner_text()).strip()
                print(name)
                print(email)
                return
            else:
                # fallback: print full row text
                try:
                    full = (await row.inner_text()).strip()
                    print(full)
                except Exception:
                    print("NOT FOUND")
                return

        # Not on this page -> try to click the Next page link scoped to its table
        pager_tables = page.get_by_role("table").filter(
            has=page.get_by_role("link", name="Go to Next page")
        )
        if await pager_tables.count() == 0:
            break
        next_link = pager_tables.first.get_by_role("link", name="Go to Next page")
        if await next_link.count() == 0:
            break
        try:
            await next_link.first.click()
        except Exception:
            # Attempt to dismiss any popup and retry once
            try:
                dialogs = page.get_by_role("dialog")
                if await dialogs.count() > 0:
                    db = dialogs.first.get_by_role("button")
                    if await db.count() > 0:
                        await db.first.click()
                        await asyncio.sleep(0.25)
                await next_link.first.click()
            except Exception:
                break

        # Wait for grid update
        try:
            await page.wait_for_load_state("networkidle", timeout=5000)
        except Exception:
            await asyncio.sleep(0.8)

    # If not found after paging
    print("NOT FOUND")
